import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';
import { readAudiences } from './src/audiences';

// One autogenerated sidebar per audience (distributors, trade customers, drivers):
// each reads only its own folder of documentation/docs, so a reader never sees
// another audience's pages. The list of audiences that have pages is written by the
// scenario-docs skill's relayout.py (documentation/docs/_audiences.json), so a new
// page or audience appears without editing this file.
const sidebars: SidebarsConfig = Object.fromEntries(
  readAudiences().map((a) => [a.id, [{ type: 'autogenerated', dirName: a.id }]]),
);

export default sidebars;
